begin;
select no_plan();
select ok((select prosecdef and provolatile='v' and ('search_path=""'=any(proconfig) or 'search_path='=any(proconfig)) from pg_proc where oid='api.initialize_current_owner_blocks_from_contact(jsonb)'::regprocedure),'Hardened volatile empty-path definer');
select ok(not has_function_privilege('anon','api.initialize_current_owner_blocks_from_contact(jsonb)','EXECUTE'),'anon execution withheld');
set local role anon;
select throws_ok($$select api.initialize_current_owner_blocks_from_contact('{}')$$,'42501',null,'Actual anon denied');
reset role;
select ok(not has_function_privilege('authenticated','api.initialize_current_owner_blocks_from_contact(jsonb)','EXECUTE'),'authenticated execution withheld');
set local role authenticated;
select throws_ok($$select api.initialize_current_owner_blocks_from_contact('{}')$$,'42501',null,'Actual authenticated denied');
reset role;
select ok(not has_function_privilege('service_role','api.initialize_current_owner_blocks_from_contact(jsonb)','EXECUTE'),'service_role execution withheld');
set local role service_role;
select throws_ok($$select api.initialize_current_owner_blocks_from_contact('{}')$$,'42501',null,'Actual service_role denied');
reset role;
select ok(not exists(select 1 from information_schema.routine_privileges where routine_schema='api' and routine_name='initialize_current_owner_blocks_from_contact' and grantee='PUBLIC'),'PUBLIC execution withheld');
set local request.jwt.claims='{}';
select is(api.initialize_current_owner_blocks_from_contact('{}'),'{"status":"unauthenticated"}'::jsonb,'No actor');
set local request.jwt.claims='{"sub":"a6000000-0000-4000-8000-000000000099","user_metadata":{"owner_id":"forged"}}';
select is(api.initialize_current_owner_blocks_from_contact('{}'),'{"status":"owner_missing"}'::jsonb,'Metadata not authority');
insert into auth.users(id,email) values
 ('a6000000-0000-4000-8000-000000000001','contact-init-one@example.test'),
 ('a6000000-0000-4000-8000-000000000002','contact-init-two@example.test'),
 ('a6000000-0000-4000-8000-000000000003','contact-init-missing@example.test');
create temporary table actors as select auth_user_id,owner_id from core.owner_auth_bindings where auth_user_id in
 ('a6000000-0000-4000-8000-000000000001','a6000000-0000-4000-8000-000000000002','a6000000-0000-4000-8000-000000000003');
update core.owner_onboarding_progress set current_step='preview_publish',primary_use_case='business' where owner_id in (select owner_id from actors);
insert into core.owner_handle_namespaces(normalized_handle,owner_id,namespace_kind)
 select 'contact-init-'||right(auth_user_id::text,6),owner_id,'current' from actors;
set local request.jwt.claims='{"sub":"a6000000-0000-4000-8000-000000000001"}';
select is(api.initialize_current_owner_blocks_from_contact('{}'),'{"status":"owner_not_eligible"}'::jsonb,'Incomplete Owner cannot initialize');
update core.owners set onboarding_completed_at=now() where id in (select owner_id from actors);
insert into core.identity_connection_working(owner_id,connection_kind,social_platform,destination_url,revision)
 select owner_id,case when auth_user_id='a6000000-0000-4000-8000-000000000001' then 'generic_link'::core.identity_connection_kind else 'social'::core.identity_connection_kind end,
 case when auth_user_id='a6000000-0000-4000-8000-000000000001' then null else 'custom_platform-1' end,
 'HTTPS://Private.example.test/Exact?X=1#Recoverable',3 from actors where auth_user_id<>'a6000000-0000-4000-8000-000000000003';

-- First Contact initialization race fixtures end here.
-- Actual foreign Text/Link/provenance rows prove preservation beyond empty tables.
insert into auth.users(id,email) values('a6000000-0000-4000-8000-000000000004','contact-init-foreign@example.test');
insert into core.identity_block_collections_working(owner_id) select owner_id from core.owner_auth_bindings where auth_user_id='a6000000-0000-4000-8000-000000000004';
insert into core.identity_blocks_working(block_id,owner_id,kind,position) select 'a6000000-0000-4000-8000-000000000014',owner_id,'text',1 from core.owner_auth_bindings where auth_user_id='a6000000-0000-4000-8000-000000000004';
insert into core.identity_blocks_working(block_id,owner_id,kind,position) select 'a6000000-0000-4000-8000-000000000015',owner_id,'generic_link',2 from core.owner_auth_bindings where auth_user_id='a6000000-0000-4000-8000-000000000004';
insert into core.identity_block_texts_working(block_id,owner_id,kind,text_content) select block_id,owner_id,kind,'Foreign raw' from core.identity_blocks_working where block_id='a6000000-0000-4000-8000-000000000014';
insert into core.identity_block_links_working(block_id,owner_id,kind,title,destination_url) select block_id,owner_id,kind,'Foreign link','https://foreign.example.test' from core.identity_blocks_working where block_id='a6000000-0000-4000-8000-000000000015';
insert into core.identity_block_initialization_provenance(owner_id,initial_block_id,source_connection_revision,source_connection_kind,source_destination_url) select owner_id,block_id,3,'generic_link','https://foreign.example.test' from core.identity_blocks_working where block_id='a6000000-0000-4000-8000-000000000015';
insert into core.identity_blocks_working(block_id,owner_id,kind,position) select 'a6000000-0000-4000-8000-000000000016',owner_id,'contact',3 from core.owner_auth_bindings where auth_user_id='a6000000-0000-4000-8000-000000000004';
insert into core.identity_block_contacts_working(block_id,owner_id,kind,contact_type,label,contact_value) select block_id,owner_id,kind,'phone','Foreign Contact','RAW Foreign' from core.identity_blocks_working where block_id='a6000000-0000-4000-8000-000000000016';
create function pg_temp.contact_intent(content text default ' <script>raw</script> ' || chr(1), visible boolean default false, subtype text default 'email', label_text text default E' Label\r\n ')
returns jsonb language sql as $$select jsonb_build_object('action','initialize_contact_block','base_collection_revision',null,'is_visible',visible,'contact_working',jsonb_build_object('kind','contact','contact_type',subtype,'label',label_text,'value',content))$$;
create temporary table purity(table_name text,value jsonb);
do $$declare name text; val jsonb; begin
 foreach name in array array['identity_connection_working','identity_block_initialization_provenance','identity_working','identity_layout_working','identity_publications','onboarding_preview_receipts','owner_auth_bindings','owner_handle_namespaces','owner_onboarding_progress','owners','identity_block_links_working','identity_block_texts_working'] loop
  execute format('select coalesce(jsonb_agg(to_jsonb(t) order by to_jsonb(t)::text),%L::jsonb) from core.%I t','[]',name) into val;
  insert into purity values(name,val);
 end loop;
end;$$;
