-- Fail at each insert boundary, including AFTER payload insertion: no partial state.
create function pg_temp.reject_contact_init() returns trigger language plpgsql as $$begin raise exception 'fixture blocked first Contact'; end;$$;
create trigger reject_contact_init before insert on core.identity_blocks_working for each row execute function pg_temp.reject_contact_init();
select throws_ok('select api.initialize_current_owner_blocks_from_contact(pg_temp.contact_intent())','P0001','fixture blocked first Contact','before identity_blocks_working failure propagates');
drop trigger reject_contact_init on core.identity_blocks_working;
select is((select count(*) from core.identity_block_collections_working where owner_id in(select owner_id from actors)),0::bigint,'Rollback no collection');
select is((select count(*) from core.identity_blocks_working where owner_id in(select owner_id from actors)),0::bigint,'Rollback no membership');
select is((select count(*) from core.identity_block_contacts_working where owner_id in(select owner_id from actors)),0::bigint,'Rollback no payload');
create trigger reject_contact_init before insert on core.identity_block_contacts_working for each row execute function pg_temp.reject_contact_init();
select throws_ok('select api.initialize_current_owner_blocks_from_contact(pg_temp.contact_intent())','P0001','fixture blocked first Contact','before identity_block_contacts_working failure propagates');
drop trigger reject_contact_init on core.identity_block_contacts_working;
select is((select count(*) from core.identity_block_collections_working where owner_id in(select owner_id from actors)),0::bigint,'Rollback no collection');
select is((select count(*) from core.identity_blocks_working where owner_id in(select owner_id from actors)),0::bigint,'Rollback no membership');
select is((select count(*) from core.identity_block_contacts_working where owner_id in(select owner_id from actors)),0::bigint,'Rollback no payload');
