select throws_ok('select api.initialize_current_owner_blocks_from_contact(pg_temp.contact_intent())','P0001','fixture blocked first Contact','after identity_block_contacts_working failure propagates');
drop trigger reject_contact_init on core.identity_block_contacts_working;
select is((select count(*) from core.identity_block_collections_working where owner_id in(select owner_id from actors)),0::bigint,'Rollback no collection');
select is((select count(*) from core.identity_blocks_working where owner_id in(select owner_id from actors)),0::bigint,'Rollback no membership');
select is((select count(*) from core.identity_block_contacts_working where owner_id in(select owner_id from actors)),0::bigint,'Rollback no payload');
create temporary table replies(value jsonb);
insert into replies values(api.initialize_current_owner_blocks_from_contact(pg_temp.contact_intent()));
select is((select array_agg(k order by k) from replies,jsonb_object_keys(value) k),array['block_id','collection_revision','status'],'Exact minimal acknowledgment');
select is((select value->>'status' from replies),'success','First Contact initialized');
select is((select value->>'collection_revision' from replies),'1','Creation revision1');
select matches((select value->>'block_id' from replies),'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','Server UUID');
select ok((select b.kind='contact' and not b.is_visible and b.position=1 and b.owner_id=(select owner_id from actors where auth_user_id='a6000000-0000-4000-8000-000000000001') from core.identity_blocks_working b where b.block_id=(select (value->>'block_id')::uuid from replies)),'Actual own hidden first Contact membership');
select is((select t.contact_value from core.identity_block_contacts_working t where t.block_id=(select (value->>'block_id')::uuid from replies)),pg_temp.contact_intent()->'contact_working'->>'value','Recoverable raw control and markup retained');
select is((select api.resolve_current_owner_contact_block_working((value->>'block_id')::uuid)->'block'->'contact_working' from replies),(pg_temp.contact_intent()->'contact_working')-'kind','Selected reader observes exact persisted raw Contact');
create temporary table initial_collection as select * from core.identity_block_collections_working;
create temporary table initial_members as select * from core.identity_blocks_working;
create temporary table initial_payloads as select * from core.identity_block_contacts_working;
select is(api.initialize_current_owner_blocks_from_contact(pg_temp.contact_intent()),'{"status":"already_initialized"}'::jsonb,'Replay is conflict, not success');
select ok(not exists((select * from core.identity_block_collections_working except select * from initial_collection) union all(select * from initial_collection except select * from core.identity_block_collections_working)),'Existing conflict retains every identity_block_collections_working column');
select ok(not exists((select * from core.identity_blocks_working except select * from initial_members) union all(select * from initial_members except select * from core.identity_blocks_working)),'Existing conflict retains every identity_blocks_working column');
select ok(not exists((select * from core.identity_block_contacts_working except select * from initial_payloads) union all(select * from initial_payloads except select * from core.identity_block_contacts_working)),'Existing conflict retains every identity_block_contacts_working column');
delete from core.identity_blocks_working where owner_id=(select owner_id from actors where auth_user_id='a6000000-0000-4000-8000-000000000001');
select is(api.initialize_current_owner_blocks_from_contact(pg_temp.contact_intent()),'{"status":"already_initialized"}'::jsonb,'Initialized-empty collection not replaced');
select is((select revision from core.identity_block_collections_working where owner_id=(select owner_id from actors where auth_user_id='a6000000-0000-4000-8000-000000000001')),1::bigint,'Empty conflict no revision bump');
set local request.jwt.claims='{"sub":"a6000000-0000-4000-8000-000000000003"}';
insert into replies values(api.initialize_current_owner_blocks_from_contact(pg_temp.contact_intent(null,true)));
select ok((select contact_value is null and kind='contact' from core.identity_block_contacts_working where owner_id=(select owner_id from actors where auth_user_id='a6000000-0000-4000-8000-000000000003')),'No source needed; present nullable Contact');
select ok((select is_visible and position=1 from core.identity_blocks_working where owner_id=(select owner_id from actors where auth_user_id='a6000000-0000-4000-8000-000000000003')),'Explicit visible retained');
select is((select count(distinct value->>'block_id') from replies),2::bigint,'Distinct server IDs across Owners');
set local request.jwt.claims='{"sub":"a6000000-0000-4000-8000-000000000002"}';
create function pg_temp.check_raw_initialization() returns setof text language plpgsql as $$declare raw text; subtype text; reply jsonb; expected jsonb; begin
 foreach subtype in array array[null,'email','whatsapp','phone'] loop
  foreach raw in array array[null,'',E'  \r\n\t  ','é🐈',repeat('🙂',2048)] loop
   expected := pg_temp.contact_intent(raw,true,subtype,repeat('🐈',512));
   reply := api.initialize_current_owner_blocks_from_contact(expected);
   return next is(reply->>'status','success','Raw first Contact accepted');
   return next is((select jsonb_build_object('kind',kind,'contact_type',contact_type,'label',label,'value',contact_value) from core.identity_block_contacts_working where block_id=(reply->>'block_id')::uuid),expected->'contact_working','Whole raw Contact tuple retained');
   delete from core.identity_block_collections_working where owner_id=(select owner_id from actors where auth_user_id='a6000000-0000-4000-8000-000000000002');
  end loop;
 end loop;
 reply := api.initialize_current_owner_blocks_from_contact(pg_temp.contact_intent(null,false,null,null));
 return next is(reply->>'status','success','Explicit all-null Contact initialized');
 return next ok((select contact_type is null and label is null and contact_value is null from core.identity_block_contacts_working where block_id=(reply->>'block_id')::uuid),'All-null payload present, not missing');
end;$$;
select * from pg_temp.check_raw_initialization();
select ok(not exists(select * from foreign_collections except select * from core.identity_block_collections_working),'All preexisting collections retained');
select ok(not exists(select * from foreign_members except select * from core.identity_blocks_working),'All preexisting memberships retained');
select ok(not exists(select * from foreign_texts except select * from core.identity_block_texts_working),'All preexisting Text payloads retained');
create function pg_temp.check_purity() returns setof text language plpgsql as $$declare item record; val jsonb; begin
 for item in select * from purity loop
  execute format('select coalesce(jsonb_agg(to_jsonb(t) order by to_jsonb(t)::text),%L::jsonb) from core.%I t','[]',item.table_name) into val;
  return next is(val,item.value,item.table_name || ' unchanged');
 end loop;
end;$$;
select ok(not exists(select * from foreign_contacts except select * from core.identity_block_contacts_working),'All preexisting Contact payloads retained');
select * from pg_temp.check_purity();
select * from finish();
rollback;
